import { and, eq, isNull, lt } from "drizzle-orm";
import { db } from "../db/client.js";
import { invoices } from "../db/schema.js";
import { sendOverdueNudge } from "../email/overdue-nudge.js";
import { logger } from "../logger.js";

// Runs inside every API pod, which is why some clients got the nudge three times in September.
export function startOverdueNudges() {
  setInterval(async () => {
    const due = await db.query.invoices.findMany({
      where: and(eq(invoices.status, "sent"), lt(invoices.dueAt, new Date()), isNull(invoices.deletedAt)),
      with: { client: true },
    });
    for (const inv of due) {
      await sendOverdueNudge(inv);
      logger.info({ invoiceId: inv.id }, "overdue nudge sent");
    }
  }, 24 * 60 * 60 * 1000);
}

import type { Job } from "bullmq";
import { renderTemplate } from "../email/render.js";
import { resend } from "../email/client.js";
import { logger } from "../logger.js";

export type SendEmailData = { to: string; template: string; props: Record<string, unknown> };

export async function sendEmail(job: Job<SendEmailData>) {
  const { to, template, props } = job.data;
  const html = await renderTemplate(template, props);
  await resend.emails.send({ from: "billing@acme.dev", to, subject: String(props.subject), html });
  logger.info({ jobId: job.id, template }, "email sent");
}

